PREFIX brick: <http://brickschema.org/schema/brick#>
SELECT ?point ?label WHERE {
  ?point rdfs:label ?label.
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?class ?tsid WHERE {
  <http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z05> brick:hasPoint ?point.
  ?point a ?class.
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid. }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?point ?tsid WHERE {
  <http://buildgraph.org/BG_small_office_2004_0000#Zone_F1_Z05.Zone_Air_Temperature_Sensor> ref:hasExternalReference ?tsid.
}
